"""Literal home heading with untouched original CSS. No measured box feeds candidate."""
from pathlib import Path
import re,ast,json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
line=next(x for x in src if x.startswith('function home('));text=line[line.index('heading('):line.index('<div class="welcome-layout">')]
pairs=[tuple(ast.literal_eval(v) for v in m) for m in re.findall(r"t\(('(?:\\.|[^'\\])*'),('(?:\\.|[^'\\])*')\)",text)];assert len(pairs)==2
cases=[dict(id=f'home-{lang}-{width}',lang=lang,width=width,title=pairs[0][lang=='en'],description=pairs[1][lang=='en'],home=True) for lang in ['ko','en'] for width in [326,438,656,700,904,1120]]
heading=next(x for x in src if x.startswith('const heading='));(o/'pageheadinghome-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
script=heading+'\nconst cases='+json.dumps(cases,ensure_ascii=False)+""";for(const c of cases){const f=document.createElement('div');f.className='fixture welcome';f.dataset.id=c.id;f.style.width=c.width+'px';f.innerHTML=heading(c.title,c.description);f.querySelector('h1').id='heading-'+c.id;document.getElementById('fixtures').append(f)}
function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const e=f.firstChild,r=e.getBoundingClientRect(),b=x=>{const q=x.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}},h=e.querySelector('h1'),p=e.querySelector('p');return{id:f.dataset.id,width:r.width,height:r.height,title:b(h),description:b(p),titleText:h.textContent,descriptionText:p.textContent,marginBottom:getComputedStyle(e).marginBottom,titleColor:getComputedStyle(h).color,descriptionColor:getComputedStyle(p).color}})}
const title=document.querySelector('.fixture h1');const live=document.getElementById('live');function state(){live.textContent=JSON.stringify({focused:document.activeElement===title,focusVisible:title.matches(':focus-visible'),focusId:document.activeElement.id,outline:getComputedStyle(title).outline,headingLevel:Number(title.tagName.slice(1))})}document.getElementById('focus-title').onclick=()=>{title.focus({preventScroll:true});state()};for(const type of ['focusin','focusout','keydown','keyup','pointerdown'])document.addEventListener(type,()=>setTimeout(state,0));state();
document.getElementById('pageheadinghome-record').onclick=async()=>{await document.fonts.ready;const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read()})});if(!res.ok)throw Error('Evidence failed');document.getElementById('pageheadinghome-record').textContent='Home heading recorded'};"""
(o/'pageheadinghome.html').write_text('<!doctype html><meta charset="utf-8"><title>Home heading · original isolation</title><link rel="stylesheet" href="pageheadinghome-original.css"><style>body{min-width:1200px}.fixture{position:absolute;left:30px;top:100px}.fixture:not(:first-child){visibility:hidden;pointer-events:none}#pageheadinghome-record{position:fixed;left:30px;top:20px}#focus-title{position:fixed;left:500px;top:20px}#after-title{position:fixed;left:30px;top:400px}#live{position:absolute;left:30px;top:450px;white-space:pre-wrap}</style><button id="pageheadinghome-record">Record Home heading</button><button id="focus-title">Focus title</button><div id="fixtures"></div><button id="after-title">Next button</button><pre id="live"></pre><script>'+script+'</script>')
for p in [o/'pageheadinghome-cases.json',r/'docs/replica/source/pageheadinghome-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'literal home heading cases')
